#!/usr/bin/env bash
# check-markdown-samples.sh — the phones' markdown renderers are tested
# against the same samples as the web's.
#
# web/src/lib/markdown-samples.json (markdown → the html_body the web send
# path produces) is generated by web/scripts/markdown-samples.ts and tested on
# the web. iOS and Android test their own renderers against copies; this
# checks the copies are the same bytes, so a sample changed on one side cannot
# leave the others testing yesterday's answer.
#
# Usage: check-markdown-samples.sh [repo root]   (default: this repository)
set -euo pipefail
ROOT="${1:-$(cd "$(dirname "$0")/.." && pwd)}"
WEB="$ROOT/web/src/lib/markdown-samples.json"
status=0
for copy in ios/MailrsTests/markdown-samples.json android/app/src/test/resources/markdown-samples.json; do
  if ! cmp -s "$WEB" "$ROOT/$copy"; then
    echo "!! $copy differs from web/src/lib/markdown-samples.json — copy it over"
    status=1
  fi
done
if [ "$status" -eq 0 ]; then
  echo "markdown samples: the web, iOS and Android copies are the same bytes"
fi
exit "$status"
